type Task = keyof typeof TASKS;
interface Metric { value?: number | null; status?: string; source?: string; seal?: string; detail?: { step?: string; start?: string; hours?: number; sha256?: string } }
interface Metrics { longestDarkH: Metric; series: unknown; t0: number }
interface SiteRow { id: string; n: number; name: string }
interface SitesDoc { sites: SiteRow[] }

holdReady();
const shell = mountShell({ screen: "evidence", onLang: draw });
const $ = (id: string) => document.getElementById(id) as HTMLElement;
const fmtH = (v: number | null | undefined): string => v == null ? t("nd") : fmtNum(v, 1) + " h";

/** Mounts a DOM node built by the core (seals, bars, layer cards) inside a Preact tree. */
function Node({ node }: { node: Node | null }) {
  return h("mp-node" as "span", { style: { display: "contents" }, ref: (host: HTMLElement | null) => { if (host && node && host.firstChild !== node) host.replaceChildren(node); } });
}

let doc: SitesDoc | null = null, site: SiteRow | null = null, m: Metrics | null = null, hours = 0, failure: string | null = null;
try {
  doc = (await loadSites()) as unknown as SitesDoc;
  const st = getState();
  site = doc.sites.find(s => s.id === st.site) || doc.sites[0];
  hours = st.hours || 336;
  m = (await apiWindowMetrics(doc as never, site as never, st.start, hours)) as unknown as Metrics;
} catch (e) { failure = String((e as Error)?.message || e); }

function CoreTiles() {
  const n = doc ? fmtNum(doc.sites.length) : t("nd");
  return <>{["map", "ctx", "card", "seal"].map(id => (
    <article class="mp-card mp-rules-tile">
      <h3>{t(`rules.core.${id}.t`)}</h3>
      <p>{t(`rules.core.${id}.d`, { n })}</p>
      {id === "seal" && (
        <div class="mp-rules-seals" data-mp-legend="">{/* seal legend, not a value */}
          {(SEALS as readonly string[]).map(k => <div><Node node={sealEl(k)} />{t("seal." + k)}</div>)}
        </div>
      )}
    </article>
  ))}</>;
}

function layerCard(layer: string): HTMLElement {
  const night = m?.longestDarkH;
  const limit: number = getState().night; // assumed limit (editable default, never a measured value)
  let answer = t("rules.card.nodata");
  if (night?.value != null) {
    const diff = limit - night.value;
    const margin = diff >= 0 ? t("rules.card.spare", { d: fmtNum(diff, 1) }) : t("rules.card.over", { d: fmtNum(-diff, 1) });
    answer = t("rules.card.answer", { h: fmtH(night.value), limit: fmtNum(limit), margin });
  }
  const why = document.createElement("div");
  render(<>{m && <Node node={barEl(dailySun(m.series as never, m.t0, hours))} />}<p class="mp-label">{t("mission.why.sun")}</p></>, why);
  const d = night?.detail || {};
  const proof = [
    [t("proof.definition"), t("rules.def.night")],
    [t("proof.step"), d.step ?? null],
    [t("proof.window"), d.start ? `${d.start.slice(0, 10)} · ${fmtNum(d.hours)} h` : null],
    [t("proof.source"), night?.source === "POST /api/compare" ? t("proof.src.compare") : (night?.source || null)],
    [t("proof.sha"), d.sha256 ?? null],
    [t("proof.status"), night?.status ?? null],
  ];
  return createLayerCard({ title: t("rules.card.title"), status: night?.status, answer, why, proof, layer }).el;
}

function Kit({ id, links, bullets }: { id: "class" | "plan"; links: [string, string][]; bullets: number }) {
  return (
    <article class="mp-card mp-rules-kit">
      <h3>{t(`rules.kit.${id}.t`)}</h3>
      <p class="mp-label">{t(`rules.kit.${id}.who`)}</p>
      <ul>{Array.from({ length: bullets }, (_, i) => <li>{t(`rules.kit.${id}.b${i + 1}`)}</li>)}</ul>
      <p>{t(`rules.kit.${id}.rule`)}</p>
      <div class="mp-rules-actions">
        {links.map(([key, page]) => <a class="mp-pill is-white" href={hrefTo(page, { ...getState(), task: id, layer: TASKS[id] })}>{t(key)}</a>)}
      </div>
    </article>
  );
}

function WhoTable() {
  const kitOf: Record<Task, string> = { explore: t("nd"), class: t("rules.kit.class.t"), plan: t("rules.kit.plan.t") };
  return (
    <table>
      <thead><tr>{["Task", "Opens", "Kit", "Extras"].map(k => <th scope="col">{t(`rules.who.col${k}`)}</th>)}</tr></thead>
      <tbody>{(Object.keys(TASKS) as Task[]).map(task => (
        <tr>
          <td><a href={hrefTo("mission.html", { ...getState(), task, layer: TASKS[task] })}>{t(`entry.${task}.title`)}</a></td>
          <td>{t("layer." + TASKS[task])}</td>
          <td>{kitOf[task]}</td>
          <td class="x">{t(`rules.who.x.${task}`)}</td>
        </tr>
      ))}</tbody>
    </table>
  );
}

function SysRules() {
  return <>{[1, 2, 3, 4, 5, 6].map(i => {
    const no = i > 4;
    return (
      <li data-no={no ? "" : undefined}>
        <span class="mk" role="img" aria-label={t(no ? "rules.no" : "rules.yes")}>{no ? "✕" : "✓"}</span>
        <div><b>{t(`rules.r${i}.t`)}</b><span class="d">{t(`rules.r${i}.d`)}</span></div>
      </li>
    );
  })}</>;
}

function draw() {
  render(<CoreTiles />, $("rules-core"));

  const ex = $("rules-example");
  if (site && m) {
    render(<>{t("rules.example", { n: site.n, name: site.name, days: fmtNum(hours / 24), date: new Date(m.t0).toISOString().slice(0, 10) })}<Node node={sealEl(m.longestDarkH.seal)} /></>, ex);
  } else render(<>{t("rules.example.nd", { msg: failure ?? t("nd") })}<Node node={sealEl("N/D")} /></>, ex);

  render(<>{["answer", "why", "proof"].map(layer => {
    const [head, ...rest] = t(`rules.cap.${layer}`).split(": ");
    return <div class="mp-rules-col"><Node node={layerCard(layer)} /><span><b>{head}</b>{": " + rest.join(": ")}</span></div>;
  })}</>, $("rules-layers"));

  render(<>
    <Kit id="class" links={[["rules.kit.class.open", "present.html"], ["rules.kit.class.open2", "activity.html"]]} bullets={2} />
    <Kit id="plan" links={[["rules.kit.plan.open", "plan.html"]]} bullets={3} />
  </>, $("rules-kits"));
  render(<WhoTable />, $("rules-who"));
  render(<SysRules />, $("rules-sys"));
  apply();
}
void shell;
draw();
markReady();
